import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { Palette, PaletteSlot, Prefs } from '../../types'
import {
  HELPER_CONFIG,
  HELPER_FRONT,
  READ_APP_MODE,
  START_HELPER,
  appModeFrom,
  backdropOf,
  coversApp,
  helperConfig,
  inkOf,
  swapsLightAndDark,
} from '../lib/appColor'
