    (lines[1] === ''
      ? ''
      : `<text x="${middle}" y="${height / 2 + 12}" text-anchor="middle" font-family="-apple-system, system-ui, sans-serif" font-size="11" fill="${ink}">${lines[1]}</text>`) +
    side(game.away, awayLogo, width - size - 2, size, ink) +
    '</svg>'
  )
}

